import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"51、【震】 震下震上","description":"周易口诀义 - 51、【震】 震下震上","frontmatter":{"title":"51、【震】 震下震上","description":"周易口诀义 - 51、【震】 震下震上"},"headers":[],"relativePath":"zh/classics/koujueyi/053.md","filePath":"zh/classics/koujueyi/053.md"}'),r={name:"zh/classics/koujueyi/053.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_51、【震】-震下震上" tabindex="-1">51、【震】 震下震上 <a class="header-anchor" href="#_51、【震】-震下震上" aria-label="Permalink to “51、【震】 震下震上”">​</a></h1><p>彖曰：震，亨。「震来虩虩」，恐致福也；「笑言哑哑」，后有则也。「震惊百里」，惊远而惧迩也。出可以守宗庙社稷，以为祭主也。</p><p>象曰：瀳雷，震；君子以恐惧修省。</p><p>初九，震来虩虩，后笑言哑哑，吉。</p><p>象曰：「震来虩虩」，恐致福也；「笑言哑哑」，后有则也。</p><p>六二，震来厉，亿丧贝，跻于九陵，勿逐，七日得。</p><p>象曰：「震来厉」，乘刚也。</p><p>六三，震苏苏，震行无眚。</p><p>象曰：「震苏苏」，位不当也。</p><p>九四，震遂泥。</p><p>象曰：「震遂泥」，未光也。</p><p>六五，震往来厉，亿无丧，有事。</p><p>象曰：「震往来厉」，危行也；其事在中，大无丧也。</p><p>上六，震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。</p><p>象曰：「震索索」，中未得也；虽凶无咎，畏邻戒也。</p><p>解读</p><p>「震亨」者，震动也，此象雷之卦，雷是天之威动也。雷之威震，人皆惊惧，因此恐惧而乃修德，恭俭整肃，所以获通，故曰</p><p>「震亨」也。「震来虩虩，笑言哑哑」者，虩虩恐惧之貌；哑哑语笑之声，故迅雷风烈，君子为之变容。天既威震，人皆恐惧，不敢怠慢，遂乃修德，道成德立，福庆亦至，福至之后，方敢喜乐，故曰「笑言哑哑」也。震惊百里，不丧匕鬯者，匕者，其形如箄，可以举鼎中之物也；鬯是香草，取之酿酒，祭庙之用也。震卦体属长子，若君出于外，或为巡狩等事，即长子监临于国，威震肃齐，广及百里。百里者，取雷震百里之义，承主祭祀粢盛之器，守而不失，故曰「不丧匕鬯」也。象曰：「瀳雷震」者，瀳者，因仍之义；雷声连续，威震相仍，雷电赫赫，故曰「瀳雷震」也。「君子以恐惧修省」者，恐，怖也；惧，惊骇也。君子立身，恒怀惊肃，若临泉谷，如履薄冰，况遇天之威怒，弥益修身，省察己过也。</p><p>「初六，震来虩虩，后笑言哑哑，吉」者，以刚处卦之先，刚则不暗于几先则能有前识，当威振之时，天威大行，而能惧以修德，遂至笑语之盛，吉福臻焉。</p><p>「六二，震来厉，亿丧贝，跻于九陵，勿逐，七日得」者，初九以刚居下，因惧修德，即是有德之人。今六二不能敬刚阳，尊有德，而反乘之，即为天之所诛罚。故威震若来，即致危厉，哀嗟伤嗟，亡其资货粮用之属也，故曰「震来厉，亿丧贝」也。亿，伤叹之辞也；贝者，资货粮用之属也。违天不敬，遂被天诛，惧天之威，而乃逃窜，威严大行，人不容舍，无粮而走，必将困危。虽超九陵，不过七日，为有司所获，故曰「跻于九陵，勿逐，七日得」也。</p><p>六三「震苏苏，震行无眚」者，苏苏，是心怀忧虑不安之貌。六三履位不正，心恒忧虑，不获安宁，故曰「震苏苏」也。虽心不安，而不乘刚，不为乖逆，故可以惧行而无灾眚，故曰「震行无眚」也。</p><p>九四「震遂泥」者，泥，沉溺也。九四以刚阳之质，在四阴之中，为四阴之主，固宜挺身独立，以安于众。若以自怀恐惧，不能挺拔，即致泥溺，沉困于难。故郑众云「身既不安，岂能安众」是也。</p><p>六五：震往来，厉。亿无丧，有事者，往即无应，来又乘刚，往之与来，不免危厉也。夫处威厉之时而居尊位，即是天助君命，威令大行，斯乃有事之机矣。故戒之曰：但保其位，守中自安，能高大其行，无所丧失，即怀大事，故曰「亿无丧，有事」也。</p><p>上六：震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。「婚媾有言」者，索索，不安不专之貌；矍矍，视不正、不审谛之容也。上六处震之极，是惧之极矣。既居极惧之地，而欲求安，亦不能得，故心怀不安，乃索索然，而所瞻视又不专审，乃矍矍矣。忧惧若此，更有征，即将有凶危至，故曰「征凶」也。若所惧之事，非是己作，若因邻家有事，惧相连及，预先防戒，即得免咎，故曰「震不于其躬，于其邻，无咎」。处极惧之时，虽复姻亲，亦不无相疑之言，故曰「婚媾有言」也。</p>',24)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
